"""Protection bundle: everything the runtime needs, generated by ``zt-adk build``, signed.

Layout of a bundle directory::

    bundle.json            index: app, fingerprint, policy version, sha256 of every file
    bundle.sig.json        Ed25519 signature of bundle.json (deployment policy key)
    system_model.json      discovered system (agents, tools, edges, workflows)
    bindings.json          canonical ids of agents / tools / workflows / interactions
    runtime_profile.json   the profile settings the runtime applies (mode, approvals, content, session)
    manifest.yaml          unified Zero Trust manifest
    pep/                 PEP plan and generated adapters (PEP generator)
    pdp_config/          identity registry and resource catalogue of the PDP
    policy_store/          signed PSL policy store (*.psl, policy_fields.yaml, *.sig.json)
    crosscheck.json        live discovery vs. static source scan
    REPORT.md              human-readable summary

The runtime verifies the signature with the policy public key of its own key directory
(never with a key from the bundle) and the hash of every file before it uses the bundle.
"""
from __future__ import annotations

import hashlib
import json
from pathlib import Path
from typing import Any

from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey

from zt_pdp.canonical import canonical_json
from zt_pdp.crypto import b64url_decode, b64url_encode, load_public_key

BUNDLE_FORMAT = 1
INDEX, SIGNATURE = "bundle.json", "bundle.sig.json"


class BundleError(RuntimeError):
    pass


def sha256_file(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def file_index(root: Path) -> dict[str, str]:
    out = {}
    for p in sorted(root.rglob("*")):
        if p.is_file() and p.name not in (INDEX, SIGNATURE) and "__pycache__" not in p.parts:
            out[p.relative_to(root).as_posix()] = sha256_file(p)
    return out


def sign_index(root: Path, index: dict[str, Any], key: Ed25519PrivateKey, *, issuer: str, key_id: str) -> None:
    (root / INDEX).write_text(json.dumps(index, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    sig = {"issuer": issuer, "key_id": key_id, "algorithm": "Ed25519",
           "index_sha256": hashlib.sha256(canonical_json(index)).hexdigest(),
           "signature": b64url_encode(key.sign(canonical_json(index)))}
    (root / SIGNATURE).write_text(json.dumps(sig, indent=2, sort_keys=True) + "\n", encoding="utf-8")


def verify_bundle(root: Path, policy_public_key_file: Path, *, expected_issuer: str) -> dict[str, Any]:
    """Signature of the index and hash of every listed file; no unlisted file may exist."""
    root = Path(root)
    try:
        index = json.loads((root / INDEX).read_text(encoding="utf-8"))
        sig = json.loads((root / SIGNATURE).read_text(encoding="utf-8"))
    except (OSError, ValueError) as exc:
        raise BundleError(f"bundle index or signature unreadable in {root}: {exc}") from exc
    if index.get("format") != BUNDLE_FORMAT:
        raise BundleError(f"unsupported bundle format {index.get('format')!r}")
    if sig.get("issuer") != expected_issuer:
        raise BundleError(f"bundle signed by {sig.get('issuer')!r}, expected {expected_issuer!r}")
    key = load_public_key(policy_public_key_file)
    try:
        key.verify(b64url_decode(str(sig.get("signature", ""))), canonical_json(index))
    except Exception as exc:
        raise BundleError("bundle signature invalid") from exc
    listed: dict[str, str] = index.get("files") or {}
    present = file_index(root)
    for name, digest in listed.items():
        if present.get(name) != digest:
            raise BundleError(f"bundle file changed or missing: {name}")
    extra = sorted(set(present) - set(listed))
    if extra:
        raise BundleError(f"bundle contains unlisted files: {extra[:5]}")
    return index
